145	    }
146	
147	    @Override
148	    @Transactional(readOnly = true)
149	    public PetType findPetTypeById(int petTypeId) {
150	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
151	    }
152	
153	    @Override
154	    @Transactional(readOnly = true)
155	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
156	        return petTypeRepository.findAll();
157	    }
158	
159	    @Override
160	    @Transactional
161	    public void savePetType(PetType petType) throws DataAccessException {
162	        petTypeRepository.save(petType);
163	    }
164	
165	    @Override
166	    @Transactional
167	    public void deletePetType(PetType petType) throws DataAccessException {
168	        petTypeRepository.delete(petType);
169	    }
170	
171	    @Override
172	    @Transactional(readOnly = true)
173	    public Specialty findSpecialtyById(int specialtyId) {
174	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
175	    }
176	
177	    @Override
178	    @Transactional(readOnly = true)
179	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
180	        return specialtyRepository.findAll();
181	    }
182	
183	    @Override
184	    @Transactional
185	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
186	        specialtyRepository.save(specialty);
187	    }
188	
189	    @Override
190	    @Transactional
191	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
192	        specialtyRepository.delete(specialty);
193	    }
194	
195	    @Override
196	    @Transactional(readOnly = true)
197	    public Collection<PetType> findPetTypes() throws DataAccessException {
198	        return petRepository.findPetTypes();
199	    }
200	
201	    @Override
202	    @Transactional(readOnly = true)
203	    public Owner findOwnerById(int id) throws DataAccessException {
204	        return findEntityById(() -> ownerRepository.findById(id));
205	    }
206	
207	    @Override
208	    @Transactional(readOnly = true)
209	    public Pet findPetById(int id) throws DataAccessException {
210	        return findEntityById(() -> petRepository.findById(id));
211	    }
212	
213	    @Override
214	    @Transactional
